create or replace function private.can_manage_sales() returns boolean language sql stable security definer set search_path=public as $$select private.zyteron_role() in('GERENTE_GENERAL','JEFE_VENTAS','COMERCIAL')$$;
create or replace function private.can_access_sales_owner(owner_id uuid) returns boolean language sql stable security definer set search_path=public as $$select private.can_manage_sales() or owner_id=auth.uid()$$;

do $$ declare table_name text;begin foreach table_name in array array['lead_sources','sales_pipelines','pipeline_stages','lost_reason_catalog','leads','lead_assignments','opportunities','opportunity_stage_history','follow_ups','discount_policies','document_templates','quotes','quote_items','quote_versions','quote_approvals','quote_recipients','quote_events','commercial_documents','quote_email_deliveries','quote_proposal_links','quote_acceptance_evidence','work_orders','sales','sales_goals','commission_rules','commissions','sales_handoffs','commercial_events','commercial_notifications','commercial_idempotency_keys'] loop execute format('alter table public.%I enable row level security',table_name);end loop;end $$;

do $$ begin
 drop policy if exists commercial_config_read on public.lead_sources;create policy commercial_config_read on public.lead_sources for select to authenticated using(active);
 drop policy if exists commercial_pipeline_read on public.sales_pipelines;create policy commercial_pipeline_read on public.sales_pipelines for select to authenticated using(active);
 drop policy if exists commercial_stage_read on public.pipeline_stages;create policy commercial_stage_read on public.pipeline_stages for select to authenticated using(active);
 drop policy if exists commercial_lost_reason_read on public.lost_reason_catalog;create policy commercial_lost_reason_read on public.lost_reason_catalog for select to authenticated using(active);
 drop policy if exists commercial_leads_scope on public.leads;create policy commercial_leads_scope on public.leads for all to authenticated using(private.can_access_sales_owner(assigned_to) or created_by=auth.uid()) with check(private.can_access_sales_owner(assigned_to) or created_by=auth.uid());
 drop policy if exists commercial_opportunities_scope on public.opportunities;create policy commercial_opportunities_scope on public.opportunities for all to authenticated using(private.can_access_sales_owner(owner_id)) with check(private.can_access_sales_owner(owner_id));
 drop policy if exists commercial_followups_scope on public.follow_ups;create policy commercial_followups_scope on public.follow_ups for all to authenticated using(private.can_access_sales_owner(assigned_to) or created_by=auth.uid()) with check(private.can_access_sales_owner(assigned_to) or created_by=auth.uid());
 drop policy if exists commercial_quotes_scope on public.quotes;create policy commercial_quotes_scope on public.quotes for all to authenticated using(private.can_access_sales_owner(owner_id)) with check(private.can_access_sales_owner(owner_id));
 drop policy if exists commercial_sales_scope on public.sales;create policy commercial_sales_scope on public.sales for select to authenticated using(private.can_access_sales_owner(owner_id) or private.zyteron_role()='FINANZAS');
 drop policy if exists commercial_goals_scope on public.sales_goals;create policy commercial_goals_scope on public.sales_goals for select to authenticated using(private.can_manage_sales() or user_id=auth.uid());
 drop policy if exists commercial_commissions_scope on public.commissions;create policy commercial_commissions_scope on public.commissions for select to authenticated using(private.can_manage_sales() or private.zyteron_role()='FINANZAS' or user_id=auth.uid());
 drop policy if exists commercial_handoffs_scope on public.sales_handoffs;create policy commercial_handoffs_scope on public.sales_handoffs for select to authenticated using(private.can_manage_sales() or private.zyteron_role() in('JEFE_DESARROLLO','DESARROLLO','OPERACIONES') or commercial_owner_id=auth.uid() or development_owner_id=auth.uid());
 drop policy if exists commercial_work_orders_scope on public.work_orders;create policy commercial_work_orders_scope on public.work_orders for select to authenticated using(private.can_manage_sales() or private.zyteron_role() in('JEFE_DESARROLLO','DESARROLLO','OPERACIONES') or commercial_owner_id=auth.uid() or development_owner_id=auth.uid());
 drop policy if exists commercial_notifications_own on public.commercial_notifications;create policy commercial_notifications_own on public.commercial_notifications for select to authenticated using(user_id=auth.uid() or audience_role=private.zyteron_role() or private.can_manage_sales());
end $$;

do $$ declare table_name text;begin foreach table_name in array array['leads','opportunities','follow_ups','quotes','sales','sales_handoffs'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=table_name)then execute format('alter publication supabase_realtime add table public.%I',table_name);end if;end loop;end $$;

